      const adopted = Math.max(values[0]!, values[1]!)
      if (!poolRollId) throw Error('advantage-reroll-missing-roll-id')
      const confirmed = await confirmPlayerD20ChoiceReroll({ rollId: `${poolRollId}:advantage-reroll`, label, targetName,
        originalValue: adopted, rollKind: 'attack', rollerTokenId: context.rollerTokenId,
        rollerCharacterId: context.rollerCharacterId, existingRollMode: rollMode, attackAbility: context.attackAbility })
