      const sourceTurnCandidates = (advanced.map.dnd5ePluginAreas ?? [])
            .filter((area) => area.sourceTokenId === boundary.tokenId)
            .flatMap((area) => collectDnd5ePersistentAreaTriggers({
              sizeRanksByTokenId,
              map: advanced.map,
              timing: boundary.timing === 'turn-start' ? 'source-turn-start' : 'source-turn-end',
              flightCapableTokenIds,
              round: boundary.round,
              areaId: area.id,
              turnKey: boundary.turnKey,
            }))
