      if (save?.type !== 'saving-throw-resolved') continue
      logs.push(`${combatant.name} 进入${areaLabels[entry.area.kind]}区域，敏捷豁免 ${save.total} vs DC ${save.dc}：${save.success ? '成功' : '失败'}。`)
