        spellId: dnd5eSpellTargeting.spellId,
        spellOriginAreaId: dnd5eSpellTargeting.spellOriginAreaId,
        focusItemInstanceId: dnd5eSpellTargeting.focusItemInstanceId,
        itemInstanceId: dnd5eSpellTargeting.itemInstanceId,
        itemUseActionId: dnd5eSpellTargeting.itemUseActionId,
        castingClassId: dnd5eSpellTargeting.castingClassId,
        racialInnate: dnd5eSpellTargeting.racialInnate,
        alternateResourceSpell: dnd5eSpellTargeting.alternateResourceSpell,
        slotLevel: dnd5eSpellTargeting.slotLevel,
        ritual: dnd5eSpellTargeting.ritual,
        activityInventoryInstanceId: dnd5eSpellTargeting.activityInventoryInstanceId,
        activityInventorySelections: dnd5eSpellTargeting.activityInventorySelections,
        activityGroundInventorySelections: dnd5eSpellTargeting.activityGroundInventorySelections,
        activityInventoryCharacterId: dnd5eSpellTargeting.activityInventoryCharacterId,
        expectedActivityInventoryRevision: dnd5eSpellTargeting.expectedActivityInventoryRevision,
        activityChoices: dnd5eSpellTargeting.activityChoices
