  const requestSharedChoiceWindow = async (input: {
    id: string
    transactionId: string
    mapId?: string
    actor?: Pick<Character, 'id'>
    actorCharId?: string
    targetCharId?: string
    pluginId: string
    featureId: string
    featureName: string
    prompt: string
    audience: 'actor' | 'target' | 'dm'
    options: Array<{ id: string; label: string; description?: string }>
    defaultOptionId: string
    timeoutMs?: number
    phase?: 'before-action' | 'before-hit' | 'before-damage' | 'after-save' | 'before-condition'
    context?: Record<string, unknown>
    fields?: PluginChoiceField[]
    onFieldValues?: (values: Record<string, string>) => void
    movementChoice?: ActivityMovementChoice
    onMovementCell?: (cell: GridCell) => void
    areaChoice?: ActivityAreaChoice
    onAreaAim?: (aim: ActivityAreaAim) => void
  }): Promise<string | undefined> => {
    const mapId = input.mapId ?? activeMap?.id
    if (!mapId || !isDM) return undefined
    const recipientId = input.audience === 'target' ? input.targetCharId : input.actor?.id ?? input.actorCharId
    const recipientOwnerId = useCharacterStore.getState().characters.find(character => character.id === recipientId)?.roomMemberId
    const audience = sharedChoiceAudience(input.audience, recipientOwnerId, roomSession?.memberId)
    const validOptionIds = new Set(input.options.map((option) => option.id))
    const readChoice = (response: PluginChoiceInterruptResponse | undefined) => {
      if (!response?.optionId || !validOptionIds.has(response.optionId)) return input.defaultOptionId
      if (input.fields?.length && response.optionId !== input.defaultOptionId) {
        const values = readPluginChoiceFields(input.fields, response.fieldValues ?? {})
        if (!values) return input.defaultOptionId
        input.onFieldValues?.(values)
      }
      if (input.movementChoice && response.optionId !== input.defaultOptionId) {
        const cell = readActivityMovementCell(response.movementCell)
        if (!cell) return input.defaultOptionId
        input.onMovementCell?.(cell)
      }
      if (input.areaChoice && response.optionId !== input.defaultOptionId) {
        const aim = readActivityAreaAim(response.areaAim)
        if (!aim) return input.defaultOptionId
        input.onAreaAim?.(aim)
      }
      return response.optionId
    }
    const selectedOption = await requestAndWaitForCombatInterrupt({
      id: input.id,
      channel: pendingSharedPluginChoiceRef,
      metadata: { actionId: input.transactionId },
      loadExisting: () => loadCombatInterrupt(mapId, input.id),
      decideExisting: (existing) => {
        if (!existing || !isCombatInterruptKind(existing, 'plugin-choice')) return { type: 'publish' }
        if (existing.status === 'pending') return { type: 'wait' }
        if (existing.status === 'answered' || existing.status === 'done') {
          return { type: 'resolve', value: readChoice(existing.response) }
        }
        return { type: 'resolve', value: input.defaultOptionId }
      },
      create: () => createCombatInterrupt<PluginChoiceInterruptPayload, PluginChoiceInterruptResponse>({
        id: input.id,
        transactionId: input.transactionId,
        mapId: mapId,
        kind: 'plugin-choice',
        phase: input.phase,
        actorCharId: input.actor?.id ?? input.actorCharId,
        targetCharId: input.targetCharId,
        payload: {
          pluginId: input.pluginId,
          featureId: input.featureId,
          featureName: input.featureName,
          prompt: input.prompt,
          audience,
          options: input.options.map((option) => ({ ...option })),
          defaultOptionId: input.defaultOptionId,
          ...input.context,
          ...(input.fields ? { fields: input.fields } : {}),
          ...(input.movementChoice ? { movementChoice: input.movementChoice } : {}),
          ...(input.areaChoice ? { areaChoice: input.areaChoice } : {}),
        },
        expiresAt: runtimeNow() + (input.timeoutMs ?? 30_000),
      }),
      publish: publishCombatInterrupt,
    })
    if ((input.fields?.length || input.movementChoice || input.areaChoice) && selectedOption !== input.defaultOptionId) {
      const answered = await loadCombatInterrupt(mapId, input.id)
      if (!answered || !isCombatInterruptKind(answered, 'plugin-choice') ||
        !['answered', 'done'].includes(answered.status)) return input.defaultOptionId
      return readChoice(answered.response)
    }
    return selectedOption
  }
  const requestActivityFlameSelections = async (input: {
    map: BattleMap
    actorId: string
    actionId: string
    packageId: string
    activity: { id: string; name: string }
    handoffs: Parameters<typeof applyDnd5eActivityDeferredMapHandoffs>[0]['handoffs']
  }): Promise<Record<string, ControlledFlameSelection> | undefined> => {
    const selections: Record<string, ControlledFlameSelection> = {}
    const actor = input.map.tokens.find(token => token.id === input.actorId)
    if (!input.handoffs.mapFlameChanges?.length) return selections
    if (!actor) return undefined
    const casterId = actor.characterId ? `character:${actor.characterId}` : JSON.stringify(['map-token', input.map.id, actor.id])
    for (const proposal of input.handoffs.mapFlameChanges) {
      // The Host map handoff resolves the unique flame at the selected area origin.
      // Do not let a second picker authorize an unrelated fire elsewhere.
      if (proposal.requireAreaOrigin) continue
      const change = proposal.change
      if ((change.kind === 'shape' || change.kind === 'illumination') && change.promptForAppearance) {
        let appearanceValues: Record<string, string> | undefined
        const accepted = await requestSharedChoiceWindow({
          id: `flame-appearance:${input.actionId}:${proposal.operationId}`, transactionId: input.actionId,
          actorCharId: actor.characterId, pluginId: input.packageId,
          featureId: input.activity.id, featureName: input.activity.name, audience: actor.characterId ? 'actor' : 'dm',
          prompt: change.kind === 'shape' ? '描述火焰中呈现的简单影像' : '选择火焰颜色',
          options: [{ id: 'apply', label: '继续选择火焰' }, { id: 'cancel', label: '取消施放' }],
          defaultOptionId: 'cancel', timeoutMs: 60_000, phase: 'before-action',
          fields: change.kind === 'shape'
            ? [{ id: 'shape', label: '影像描述', kind: 'text', required: true }]
            : [{ id: 'color', label: '火焰颜色', kind: 'color', required: true, defaultValue: change.color ?? '#ffaa00' }],
          onFieldValues: values => { appearanceValues = values },
        })
        if (accepted !== 'apply' || !appearanceValues) return undefined
        proposal.change = change.kind === 'shape'
          ? { kind: 'shape', description: appearanceValues.shape }
          : { kind: 'illumination', multiplier: change.multiplier, color: appearanceValues.color }
      }
      const selected = await requestControlledFlameSelection({
        readScene: () => ({
          map: useMapStore.getState().maps.find(map => map.id === input.map.id) ?? { ...input.map, tokens: [] },
          geometries: useMapGeometryStore.getState().maps,
          actorTokenId: actor.id, casterId,
          actionId: `${input.actionId}:${proposal.operationId}`,
          worldMinute: useCampaignTimeStore.getState().state.worldMinute,
        }),
        intent: proposal.change,
        choose: options => requestSharedChoiceWindow({
          id: `flame-choice:${input.actionId}:${proposal.operationId}`,
          transactionId: input.actionId, actorCharId: actor.characterId,
          pluginId: input.packageId, featureId: input.activity.id, featureName: input.activity.name,
          audience: actor.characterId ? 'actor' : 'dm',
          prompt: proposal.change.kind === 'ignite-touch' ? '选择要触碰点燃的物体' : proposal.change.kind === 'spread' ? '选择火焰与蔓延目的地' : proposal.change.kind === 'dismiss' ? '选择要解除的火焰效果' : '选择要改变的火焰',
          options: [...options, { id: 'cancel', label: '取消施放' }],
          defaultOptionId: 'cancel', timeoutMs: 60_000, phase: 'before-action',
        }),
      })
      if (!selected) return undefined
      selections[proposal.operationId] = selected
    }
    return selections
  }
  const requestActivityWaterSelections = async (input: {
    map: BattleMap; actorId: string; actionId: string; packageId: string;
    activity: {id:string;name:string};
    handoffs: Parameters<typeof applyDnd5eActivityDeferredMapHandoffs>[0]['handoffs'];
    areaSelection: Parameters<typeof applyDnd5eActivityDeferredMapHandoffs>[0]['areaSelection'];
  }): Promise<Record<string,ControlledWaterSelection>|undefined> => {
    const selections:Record<string,ControlledWaterSelection>={}
    if (!input.handoffs.mapWaterChanges?.length) return selections
    const actor=input.map.tokens.find(token=>token.id===input.actorId)
    if(!actor)return undefined
    const placement=input.areaSelection?.areaPlacement
    const region=placement?{center:{x:placement.x,y:placement.y},
      dimensionsFeet:{x:placement.widthFeet??5,y:placement.lengthFeet??5,z:placement.heightFeet??5},
      baseElevationFeet:placement.elevationFeet??0}:undefined
    for(const proposal of input.handoffs.mapWaterChanges){
      const change=proposal.change
      if(change.promptForChange){
        let values:Record<string,string>|undefined
        const accepted=await requestSharedChoiceWindow({id:`water-input:${input.actionId}:${proposal.operationId}`,
          transactionId:input.actionId,actorCharId:actor.characterId,pluginId:input.packageId,
          featureId:input.activity.id,featureName:input.activity.name,audience:actor.characterId?'actor':'dm',
          prompt:change.kind==='move'?'设置水体位移，合计不超过 5 尺':change.kind==='shape'?'描述水体呈现的简单形状':'设置选中水体的颜色与透明度',
          options:[{id:'apply',label:'继续'},{id:'cancel',label:'取消施放'}],defaultOptionId:'cancel',timeoutMs:60_000,phase:'before-action',
          fields:change.kind==='move'?[
            {id:'x',label:'向右位移（尺，负数向左）',kind:'text',required:true,defaultValue:String(change.displacementFeet.x)},
            {id:'y',label:'向下位移（尺，负数向上）',kind:'text',required:true,defaultValue:String(change.displacementFeet.y)},
            {id:'z',label:'高度变化（尺，负数降低）',kind:'text',required:true,defaultValue:String(change.displacementFeet.z)},
          ]:change.kind==='appearance'?[
            {id:'color',label:'水体颜色',kind:'color',required:true,defaultValue:change.color},
            {id:'opacity',label:'不透明度（0 至 1）',kind:'text',required:true,defaultValue:String(change.opacity)},
          ]:[{id:'description',label:'简单形状描述',kind:'text',required:true},{id:'drawing',label:'绘制水体形状（可选）',kind:'surface-drawing'}],
          onFieldValues:inputValues=>{values=inputValues},
        })
        if(accepted!=='apply'||!values)return undefined
        const resolved=resolveControlledWaterInput(change,values)
        if(!resolved)return undefined
        proposal.change=resolved
      }
      const selected=await requestControlledWaterSelection({
        readScene:()=>({map:useMapStore.getState().maps.find(map=>map.id===input.map.id)??{...input.map,tokens:[]},
          geometries:useMapGeometryStore.getState().maps,actorTokenId:actor.id,
          casterId:actor.characterId?`character:${actor.characterId}`:JSON.stringify(['map-token',input.map.id,actor.id]),
          actionId:`${input.actionId}:${proposal.operationId}`,rules:proposal.rules,worldMinute:useCampaignTimeStore.getState().state.worldMinute}),
        intent:proposal.change,region,
        choose:options=>requestSharedChoiceWindow({id:`water-choice:${input.actionId}:${proposal.operationId}`,
          transactionId:input.actionId,actorCharId:actor.characterId,pluginId:input.packageId,
          featureId:input.activity.id,featureName:input.activity.name,audience:actor.characterId?'actor':'dm',
          prompt:proposal.change.kind==='dismiss'?'选择要解除的操水效果':'选择范围内的水体',
          options:[...options,{id:'cancel',label:'取消施放'}],defaultOptionId:'cancel',timeoutMs:60_000,phase:'before-action'}),
      })
      if(!selected)return undefined
      selections[proposal.operationId]=selected
    }
    return selections
  }
