  const requestSharedPluginChoice = async (
    prepared: PreparedDnd5ePluginFeatureAction,
  ): Promise<string | undefined> => {
    const declaration = prepared.feature.action?.interrupt
    if (!declaration) return undefined
    const interruptId = `plugin-choice:${prepared.action.id}`
    const assistedDmBoundary = isAssistedDmBoundaryChoice(declaration)
    if (assistedDmBoundary) {
      await activateDmAdjudicationPause({
        interruptId,
        label: prepared.feature.name,
      })
    }
    const choice = await requestSharedChoiceWindow({
      id: interruptId,
      transactionId: prepared.action.id,
      actor: prepared.actor,
      targetCharId: prepared.targetToken.characterId,
      pluginId: prepared.feature.ownerPluginId,
      featureId: prepared.feature.id,
      featureName: prepared.feature.name,
      prompt: declaration.prompt,
      audience: declaration.audience,
      options: declaration.options.map((option) => ({ ...option })),
      defaultOptionId: declaration.defaultOptionId,
      timeoutMs: declaration.timeoutMs,
    })
    if (assistedDmBoundary) {
      await waitForDmAdjudicationResume({ id: interruptId })
    }
    return choice
  }
  const buildDnd5eCombatManeuverReactionWeaponAttack = async (input: {
    map: BattleMap
    actorToken: Token
    targetToken: Token
    label: string
  }): Promise<{
    weaponAttack: Dnd5eCombatManeuverReactionWeaponAttack
    hit: boolean
    critical: boolean
  } | undefined> => {
    const characters = useCharacterStore.getState().characters
    const prepared = prepareDnd5eOpportunityAttack({
      initiativeIndex: initiativeIndexRef.current,
      combatId: combatIdRef.current || `map-${input.map.id}`,
      round: roundRef.current,
      map: input.map,
      characters,
      initiativeOrder: initiativeOrderRef.current,
      actorTokenId: input.actorToken.id,
      targetTokenId: input.targetToken.id,
      turnEconomy: currentDnd5eTurnEconomy(input.actorToken.id),
      targetTurnEconomy: currentDnd5eTurnEconomy(input.targetToken.id),
    })
    if (!prepared.ok) return undefined
    const attack = prepared.prepared
    const actorCombatant = attack.state.combatants[input.actorToken.id]
    if (!actorCombatant) return undefined
    const actorCharacter = input.actorToken.characterId
      ? characters.find((character) => character.id === input.actorToken.characterId)
      : undefined
    await publishSingleTargetAttackPresentation({
      mapId: input.map.id,
      sourceTokenId: input.actorToken.id,
      targetTokenId: input.targetToken.id,
      actorName: attack.actorName,
      attackName: attack.weaponName,
      attackKind: 'melee',
      character: actorCharacter,
    })
    attack.areaAttackAdvantageReaction = await requestAreaAttackAdvantageReaction({
      map: input.map, state: attack.state, attacker: input.actorToken, target: input.targetToken,
      attackName: `${input.label}·${attack.weaponName}`, excludedSourceIds: new Set([input.actorToken.id]),
    })
    const effectiveAttackMode = dnd5eOpportunityAttackModeResolution(attack).mode
    const attackRollContext = {
      checkPreview: createDiceCheckPreview('attack', attack.actorName, attack.targetName, (a,b) => previewDnd5eOpportunityAttack(attack,a,b).hit, effectiveAttackMode, previewDnd5eOpportunityAttack(attack,1,1).roll.modifier),
      rollKind: 'attack' as const,
      rollerTokenId: input.actorToken.id,
      rollerCharacterId: actorCharacter?.id,
      targetCharacterId: input.targetToken.characterId,
    }
    const [d20, d20Second] = await rollDiceBoxD20Pair(`${input.label}·${attack.weaponName}命中检定`, attack.targetName, effectiveAttackMode, attackRollContext)
    const halflingLuckyD20 = actorCombatant.racialRules?.halflingLucky && d20 === 1
      ? await rollDiceBoxD20('半身人幸运·反应攻击重掷', attack.actorName, {
          ...attackRollContext,
          skipChoiceReroll: true,
        })
      : undefined
    const halflingLuckyD20Second = actorCombatant.racialRules?.halflingLucky && d20Second === 1
      ? await rollDiceBoxD20('半身人幸运·反应攻击重掷', attack.actorName, {
          ...attackRollContext,
          skipChoiceReroll: true,
        })
      : undefined
    const blessRoll = attack.blessed
      ? (await rollDiceBoxValues(1, 4, `祝福术·${input.label}攻击加值`, attack.actorName, { rollerTokenId: attack.actorToken.id }))[0]
      : undefined
    const baneRoll = attack.baned
      ? (await rollDiceBoxValues(1, 4, `灾祸术·${input.label}攻击减值`, attack.actorName, { rollerTokenId: attack.actorToken.id }))[0]
      : undefined
    const preview = previewDnd5eOpportunityAttack(
      attack,
      halflingLuckyD20 ?? d20,
      halflingLuckyD20Second ?? d20Second,
      blessRoll,
      baneRoll,
    )
    const damageRolls = preview.hit
      ? await rollDiceBoxValues(
          attack.damage.count * (preview.critical ? 2 : 1),
          attack.damage.sides,
          `${input.label}·${attack.weaponName}伤害`,
          attack.targetName, { rollerTokenId: attack.actorToken.id },
        )
      : []
    const classDamageDefinitions = preview.hit
      ? dnd5eOpportunityAttackClassDamageDefinitions(attack, preview.critical)
      : []
    const classDamageRolls: Dnd5eClassDamageRolls[] = []
    for (const definition of classDamageDefinitions) {
      const count = definition.count * (preview.critical && definition.doubleOnCritical ? 2 : 1)
      classDamageRolls.push({
        source: definition.source,
        rollId: definition.rollId,
        rolls: count > 0
          ? await rollDiceBoxValues(
              count,
              definition.sides,
              `${input.label}·${definition.source}`,
              attack.targetName, { rollerTokenId: attack.actorToken.id },
            )
          : [],
      })
    }
    const inventorySettlement = await coordinateDnd5eReactionAttackInventorySettlement({
      state: attack.state,
      actor: actorCombatant,
      weaponId: attack.classDamageContext?.weaponId, targetCreatureType: attack.state.combatants[input.targetToken.id]?.creatureType,
      hit: preview.hit,
      critical: preview.critical,
      targetLabel: attack.targetName,
      rollDice: rollDiceBoxValues,
    })
    return {
      hit: preview.hit,
      critical: preview.critical,
      weaponAttack: {
        areaAttackAdvantageReaction: attack.areaAttackAdvantageReaction,
        attackModifier: attack.attackModifier,
        criticalThreshold: attack.criticalThreshold,
        d20,
        d20Second,
        halflingLuckyD20,
        halflingLuckyD20Second,
        blessRoll,
        baneRoll,
        mode: attack.attackMode,
        damage: { ...attack.damage, rolls: damageRolls },
        classDamageContext: attack.classDamageContext,
        classDamageRolls,
        inventoryEffectRolls: inventorySettlement.inventoryEffectRolls,
      },
    }
  }
