  const requestDnd5eSourceActionInterruption = async (input: {
    state: Dnd5eHeadlessCombatState
    sourceId: string
    event: 'spell-cast' | 'teleport'
    actionName: string
    characters: readonly Character[]
    characterIdByCombatantId: Readonly<Record<string, string>>
    transactionId: string
  }) => {
    const source = input.state.combatants[input.sourceId]
    if (!source) return undefined
    const characterFor = (id: string) => input.characters.find(character => character.id === input.characterIdByCombatantId[id])
    const sourceCharacter = characterFor(source.id)
    let previewState = input.state
    const attempts: Dnd5eSourceActionInterruptionReaction[] = []
    const collected = () => {
      if (!attempts.length) return undefined
      const reaction = { ...attempts[0]!, subsequentReactions: attempts.slice(1) }
      const result = previewDnd5eSourceActionInterruptionResolution(input.state, input.sourceId, input.event, reaction)
      if (!result) throw new Error('invalid-source-interruption-sequence')
      return { reaction, ...result }
    }
    for (const option of dnd5eSourceActionInterruptionOptions(input.state, source.id, input.event)) {
      if (!dnd5eSourceActionInterruptionOptions(previewState, input.sourceId, input.event)
        .some(current => current.actorId === option.actorId && current.featureId === option.featureId)) continue
      const source = previewState.combatants[input.sourceId]
      const reactor = previewState.combatants[option.actorId]
      const character = characterFor(reactor.id)
      const prompt = `${source.name} 正在${input.event === 'spell-cast' ? '施放' : '使用'}${input.actionName}。是否消耗反应和“${option.featureName}”？对方将进行${combatPresentationSavingThrowAbilityLabel(option.saveAbility)}（DC ${option.dc}），失败则阻止本次${input.event === 'spell-cast' ? '施法' : '传送'}。`
      const choice = character ? await requestSharedChoiceWindow({
        id: runtimeId('source-action-interruption'), transactionId: input.transactionId, actor: character,
        pluginId: dnd5ePluginFeatureDefinition(option.featureId)?.ownerPluginId ?? 'dnd5e-activity',
        featureId: option.featureId, featureName: option.featureName, prompt, audience: 'actor',
        options: [{ id: 'use', label: `使用${option.featureName}` }, { id: 'decline', label: '保留反应' }],
        defaultOptionId: 'decline', timeoutMs: 30_000, phase: 'before-action',
      }) : await showCombatDialog({ title: option.featureName, message: prompt,
        confirmText: `使用${option.featureName}`, cancelText: '保留反应', tone: 'violet' }) ? 'use' : 'decline'
      if (choice !== 'use') continue
      let mode = dnd5eSavingThrowMode(source, option.saveAbility, { sourceActorId: reactor.id })
      let disadvantageNegationChoice: Dnd5eSourceActionInterruptionReaction['disadvantageNegationChoice']
      if (mode === 'disadvantage' && sourceCharacter && activeMap) {
        const contextId = `source-interruption:${input.event}:${reactor.id}:${option.featureId}`
        const character = { ...sourceCharacter, classResources: structuredClone(source.classResources) }
        const roll = { rollId: runtimeId('source-interruption-save'), characterId: character.id,
          kind: 'saving-throw' as const, mode, phase: 'before-roll' as const, contextId }
        const beforeChoice = JSON.stringify([useMapStore.getState().maps, useCharacterStore.getState().characters])
        const choice = await requestDisadvantageNegation({
          mapId: activeMap.id, transactionId: input.transactionId, character, roll,
        }, {
          choose: requestSharedChoiceWindow, deferToParentTransaction: true,
          isCurrent: () => JSON.stringify([useMapStore.getState().maps, useCharacterStore.getState().characters]) === beforeChoice,
        })
        if (choice?.used) {
          if (!planDnd5eDisadvantageNegation(character, roll, choice.featureId))
            throw new Error('source-interruption-negation-unavailable')
          disadvantageNegationChoice = { featureId: choice.featureId, rollId: roll.rollId,
            transactionId: input.transactionId, contextId }
          mode = 'normal'
        }
      }
      const [savingThrowD20, savingThrowD20Second] = await rollDiceBoxD20Pair(
        `${option.featureName}·${combatPresentationSavingThrowAbilityLabel(option.saveAbility)}`, source.name, mode,
        { rollerTokenId: source.id, rollKind: 'saving-throw' })
      const reaction: Dnd5eSourceActionInterruptionReaction = { actorId: reactor.id, featureId: option.featureId,
        savingThrowD20, savingThrowD20Second, disadvantageNegationChoice }
      if (source.racialRules?.halflingLucky && savingThrowD20 === 1)
        reaction.halflingLuckyD20 = await rollDiceBoxD20('半身人幸运·豁免重投', source.name, { rollerTokenId: source.id, rollKind: 'saving-throw' })
      if (source.racialRules?.halflingLucky && savingThrowD20Second === 1)
        reaction.halflingLuckyD20Second = await rollDiceBoxD20('半身人幸运·豁免重投', source.name, { rollerTokenId: source.id, rollKind: 'saving-throw' })
      if (dnd5eCombatantHasConcentrationEffect(previewState, source.id, 'bless'))
        reaction.blessRoll = (await rollDiceBoxValues(1, 4, '祝福术·豁免加值', source.name, { rollerTokenId: source.id }))[0]
      if (dnd5eCombatantHasConcentrationEffect(previewState, source.id, 'bane'))
        reaction.baneRoll = (await rollDiceBoxValues(1, 4, '灾祸术·豁免减值', source.name, { rollerTokenId: source.id }))[0]
      const preview = () => {
        const result = previewDnd5eSourceActionInterruptionResolution(previewState, source.id, input.event, reaction)
        if (!result?.savingThrow) throw new Error('invalid-source-interruption-save')
        return { ...result, savingThrow: result.savingThrow }
      }
      let result = preview()
      const sourceToken = activeMap?.tokens.find(token => token.id === source.id)
      if (activeMap && sourceToken && (
        (sourceToken.type === 'enemy' && result.savingThrow.success) ||
        (sourceToken.type === 'player' && !result.savingThrow.success)
      )) {
        const confirmation = await confirmSuccessfulEnemyD20({
          map: activeMap, characters: input.characters,
          label: `${option.featureName}·${combatPresentationSavingThrowAbilityLabel(option.saveAbility)}`,
          targetName: sourceToken.label, originalValue: result.savingThrow.d20,
          rollerCharacterId: sourceCharacter?.id,
          state: previewState, affectedId: source.id, rollKind: 'saving-throw',
          outcome: result.savingThrow.success ? 'success' : 'failure',
          currentTotal: result.savingThrow.total, targetNumber: option.dc,
          naturalOne: result.savingThrow.d20 === 1,
          naturalTwenty: result.savingThrow.d20 === 20,
          reservedReactionSourceIds: new Set([reactor.id]),
        })
        reaction.postD20Adjustment = confirmation.postD20Adjustment
        if (confirmation.value !== result.savingThrow.d20) {
          reaction.savingThrowD20 = confirmation.value
          if (mode !== 'normal') reaction.savingThrowD20Second = confirmation.value
          // The replacement is the resolved die; do not reuse luck rerolls of the old dice.
          reaction.halflingLuckyD20 = undefined
          reaction.halflingLuckyD20Second = undefined
        }
        result = preview()
      }
      if (result.interrupted && source.classState.bardicInspirationDie) {
        reaction.bardicInspirationRoll = await requestDnd5eBardicInspirationRoll({
          target: sourceCharacter, targetName: source.name, dieSides: source.classState.bardicInspirationDie,
          rollType: '豁免', total: result.savingThrow.total, targetNumber: option.dc, rollerTokenId: source.id })
        result = preview()
      }
      if (result.interrupted && dnd5eDarkOnesOwnLuckAvailable(source)) {
        reaction.darkOnesOwnLuckRoll = await requestDnd5eDarkOnesOwnLuckRoll({
          target: sourceCharacter, targetName: source.name, rollType: '豁免', total: result.savingThrow.total, targetNumber: option.dc })
        result = preview()
      }
      const optional = await requestDnd5eOptionalBonusDieUse({
        target: sourceCharacter, combatant: source, source: { actorId: reactor.id, kind: 'saving-throw' },
        checkKey: option.featureId, rollKind: 'saving-throw', rollType: '豁免',
        originalD20: result.savingThrow.d20, total: result.savingThrow.total, targetNumber: option.dc })
      if (optional) { reaction.optionalBonusDice = [optional]; result = preview() }
      if (result.interrupted && sourceCharacter) {
        const reroll = await requestDnd5eSavingThrowRerollDice({ target: sourceCharacter, targetName: source.name,
          featureName: option.featureName, total: result.savingThrow.total, dc: option.dc, mode })
        if (reroll) {
          reaction.rerollResourceKey = reroll.resourceKey
          reaction.rerollD20 = reroll.d20
          reaction.rerollD20Second = reroll.d20Second
          result = preview()
        }
      }
      if (result.interrupted && (source.classState.legendaryResistanceUses ?? 0) > 0) {
        reaction.legendaryResistance = await requestSharedLegendaryResistanceChoice({
          targetTokenId: source.id, targetName: source.name, effectName: option.featureName,
          total: result.savingThrow.total, dc: option.dc, remainingUses: source.classState.legendaryResistanceUses! })
        result = preview()
      }
      attempts.push(reaction)
      previewState = result.state
      if (result.interrupted) return collected()
    }
    return collected()
  }
  const requestDnd5eActivityTeleportInterruptions = async (input: {
    state: Dnd5eHeadlessCombatState
    actorId: string
    movements: readonly { operationId: string; targetId: string; mode: string }[]
    actionName: string
    characters: readonly Character[]
    characterIdByCombatantId: Readonly<Record<string, string>>
    transactionId: string
  }): Promise<Dnd5eActivityTeleportInterruptionUse[]> => {
    if (!input.state.active) return []
    let previewState = input.state
    const uses: Dnd5eActivityTeleportInterruptionUse[] = []
    const cancelledSwaps = new Set<string>()
    for (const movement of input.movements) {
      if (movement.mode !== 'teleport' && movement.mode !== 'swap') continue
      if (cancelledSwaps.has(movement.operationId)) continue
      const sourceIds = movement.mode === 'swap'
        ? [...new Set([input.actorId, movement.targetId])] : [movement.targetId]
      for (const sourceId of sourceIds) {
        const choice = await requestDnd5eSourceActionInterruption({
          ...input, state: previewState, sourceId, event: 'teleport',
        })
        if (!choice) continue
        uses.push({ operationId: movement.operationId, targetId: sourceId, reaction: choice.reaction })
        previewState = choice.state
        if (choice.interrupted) {
          if (movement.mode === 'swap') cancelledSwaps.add(movement.operationId)
          break
        }
      }
    }
    return uses
  }
  const requestDnd5eSpellInterceptionReaction = async (input: {
    state: Dnd5eHeadlessCombatState
    caster: Dnd5eCombatant
    casterName: string
    casterTokenId: string
    spellId: string
    spellName: string
    spellLevel: number
    targetTokens: readonly Token[]
    characters: readonly Character[]
    characterIdByCombatantId: Readonly<Record<string, string>>
    transactionId: string
  }): Promise<Dnd5eSpellInterceptionReaction | undefined> => {
    if (input.spellLevel < 1) return undefined
    for (const targetToken of [...input.targetTokens].sort((left, right) => left.id.localeCompare(right.id))) {
      const reactor = input.state.combatants[targetToken.id]
      if (!reactor || reactor.controller === input.caster.controller || reactor.currentHp <= 0) continue
      const characterId = input.characterIdByCombatantId[reactor.id] ?? targetToken.characterId
      const character = characterId
        ? input.characters.find((candidate) => candidate.id === characterId)
        : undefined
      for (const option of dnd5eSpellInterceptionOptions(reactor, input.spellLevel)) {
        const choice = character
          ? await requestSharedChoiceWindow({
              id: runtimeId(`spell-interception:${option.featureId}`),
              transactionId: input.transactionId,
              actor: character,
              pluginId: dnd5ePluginFeatureDefinition(option.featureId)?.ownerPluginId ?? 'dnd5e-activity',
              featureId: option.featureId,
              featureName: option.featureName,
              prompt: `${input.casterName} 正在施放${input.spellName}，并将影响 ${character.name}。是否消耗反应和“${option.featureName}”？施法者随后进行${combatPresentationSavingThrowAbilityLabel(option.saveAbility)}（DC ${option.dc}）。`,
              audience: 'actor',
              options: [
                { id: 'use', label: `使用${option.featureName}` },
                { id: 'decline', label: '保留反应' },
              ],
              defaultOptionId: 'decline',
              timeoutMs: 30_000,
              phase: 'before-action',
              context: { spellId: input.spellId, spellLevel: input.spellLevel },
            })
          : await showCombatDialog({
              title: option.featureName,
              message: `${input.casterName} 正在施放${input.spellName}，并将影响 ${reactor.name}。\n是否消耗反应使用${option.featureName}？施法者随后进行${combatPresentationSavingThrowAbilityLabel(option.saveAbility)}（DC ${option.dc}）。`,
              confirmText: `使用${option.featureName}`,
              cancelText: '保留反应',
              tone: 'violet',
            }) ? 'use' : 'decline'
        if (choice !== 'use') continue
        const saveMode = dnd5eSavingThrowMode(input.caster, option.saveAbility, {
          sourceIsMagical: true,
        })
        const saveLabel = `${option.featureName}·${combatPresentationSavingThrowAbilityLabel(option.saveAbility)}`
        const [savingThrowD20, savingThrowD20Second] = await rollDiceBoxD20Pair(saveLabel, input.casterName, saveMode, { rollerTokenId: input.casterTokenId, rollKind: 'saving-throw' })
        const halflingLuckyD20 = input.caster.racialRules?.halflingLucky && savingThrowD20 === 1
          ? await rollDiceBoxD20(`半身人幸运·${option.featureName}豁免重投`, input.casterName, { rollerTokenId: input.casterTokenId, rollKind: 'saving-throw' })
          : undefined
        const halflingLuckyD20Second = input.caster.racialRules?.halflingLucky && savingThrowD20Second === 1
          ? await rollDiceBoxD20(`半身人幸运·${option.featureName}豁免重投`, input.casterName, { rollerTokenId: input.casterTokenId, rollKind: 'saving-throw' })
          : undefined
        const blessRoll = dnd5eCombatantHasConcentrationEffect(input.state, input.caster.id, 'bless')
          ? (await rollDiceBoxValues(1, 4, `祝福术·${option.featureName}豁免加值`, input.casterName, { rollerTokenId: input.casterTokenId }))[0]
          : undefined
        const baneRoll = dnd5eCombatantHasConcentrationEffect(input.state, input.caster.id, 'bane')
          ? (await rollDiceBoxValues(1, 4, `灾祸术·${option.featureName}豁免减值`, input.casterName, { rollerTokenId: input.casterTokenId }))[0]
          : undefined
        return {
          actorId: reactor.id,
          featureId: option.featureId,
          savingThrowD20,
          savingThrowD20Second,
          halflingLuckyD20,
          halflingLuckyD20Second,
          blessRoll,
          baneRoll,
        }
      }
    }
    return undefined
  }
  const requestSharedLegendaryResistanceChoice = async (params: {
    targetTokenId: string
    targetName: string
    effectName: string
    total: number
    dc: number
    remainingUses: number
  }): Promise<boolean> => {
    if (!activeMap || !isDM || params.remainingUses < 1) return false
    const id = runtimeId()
    const interrupt = createCombatInterrupt<LegendaryResistanceInterruptPayload, LegendaryResistanceInterruptResponse>({
      id,
      transactionId: activeInterruptTransactionIdRef.current ?? id,
      mapId: activeMap.id,
      kind: 'legendary-resistance',
      phase: 'after-save',
      targetCharId: params.targetTokenId,
      payload: {
        targetName: params.targetName,
        effectName: params.effectName,
        total: params.total,
        dc: params.dc,
        remainingUses: params.remainingUses,
      },
      expiresAt: runtimeNow() + 60_000,
    })
    await publishCombatInterrupt(interrupt)
    const useLegendaryResistance = await showCombatDialog({
      title: '传奇抗性',
      message: `${params.targetName} 对 ${params.effectName} 的豁免失败（${params.total} vs DC ${params.dc}）。\n是否消耗 1 次传奇抗性，将本次豁免改为成功？\n剩余 ${params.remainingUses} 次。`,
      confirmText: '使用传奇抗性',
      cancelText: '保留次数',
      tone: 'amber',
    })
    const response = { useLegendaryResistance }
    await answerSharedCombatInterrupt(id, response)
    await finishSharedCombatInterrupt(id, response)
    return useLegendaryResistance
  }
