  async function requestDnd5eSavingThrowRerollDice(input: {
    target: Character
    targetName: string
    featureName: string
    total: number
    dc: number
    mode: 'normal' | 'advantage' | 'disadvantage'
    usedRerollResourceKeys?: readonly string[]
  }): Promise<{ d20: number; d20Second?: number; resourceKey?: string } | undefined> {
    const actor = createCombatantFromDnd5eCharacter({character:migrateCharacterToDnd5e(input.target),controller:'player',initiativeD20:10,position:{x:0,y:0}})
    const options = dnd5eSavingThrowRerollFeatures(actor).filter(option => {
      const spent = input.usedRerollResourceKeys?.filter(key => key === option.resourceKey).length ?? 0
      return (option.remainingUses ?? actor.classResources[option.resourceKey]?.current ?? 0) > spent
    })
    let selected = options[0]
    if (options.length > 1 && activeMap && isDM) {
      const id=runtimeId()
      const key=await requestSharedChoiceWindow({id,transactionId:activeInterruptTransactionIdRef.current??id,
        actorCharId:input.target.id,pluginId:'srd-5.1',featureId:'saving-throw-reroll',featureName:'选择豁免重掷能力',
        prompt:`${input.targetName} 的豁免结果 ${input.total} 未达到 DC ${input.dc}。选择要消耗的能力；重掷后必须采用新结果。`,
        audience:'actor',options:[{id:'decline',label:'保留全部资源'},...options.map(option=>({id:option.resourceKey,label:option.name}))],
        defaultOptionId:'decline',timeoutMs:60000,phase:'after-save'})
      selected=options.find(option=>option.resourceKey===key)!
      if(!selected)return undefined
    } else {
      if(!selected)return undefined
      const accepted=await requestSharedSavingThrowRerollChoice(input.target,{featureName:selected.name,total:input.total,dc:input.dc})
      if(!accepted)return undefined
    }
    const [d20,d20Second]=await rollDiceBoxD20Pair(`${selected.name}·豁免重掷`,input.targetName,input.mode,{rollerCharacterId:input.target.id,rollKind:'saving-throw'})
    return {d20,d20Second,resourceKey:selected.resourceKey}
  }
