        spellCast.characters = spellCast.characters.map(character => character.id === fresh.id ? fresh : character)
        const actor = spellCast.state.combatants[spellCast.actorToken.id]
        actor.classResources = structuredClone(fresh.classResources ?? {})
        actor.classState.disadvantageNegationReceipts = structuredClone(fresh.dnd5eCombatState?.disadvantageNegationReceipts)
