      const effectiveAttackTotal = attackTotalBeforeCuttingWords - (cuttingWords?.roll ?? 0)
      const attackHitAfterCuttingWords = criticalRangeHit || (!preview.roll.naturalOne &&
        effectiveAttackTotal >= attack.targetArmorClass)
