            const replacement=(await rollDiceBoxValues(1,20,`${choice.feature.name}·重骰`,attack.targetToken.label,{rollerTokenId:attack.actorToken.id}))[0]
            missedWeaponAttackReroll={featureId:choice.feature.id,d20:replacement,dieIndex:choice.dieIndex}
