            commandId: `${action.id}:equipment-reroll`,
            transactionId: attackTransaction.id,
            actorId: attack.actor.id,
            instanceId: equipmentRerollCommit.instanceId,
            effectId: equipmentRerollCommit.effectId,
            resourceId: equipmentRerollCommit.resourceId,
            rollLedgerEntryId: equipmentRerollCommit.rollLedgerEntryId,
