        const returnTarget = returnAccepted ? await selectDnd5eDeflectedMissileReturnTarget({state:resolved.result.state,map:resolved.application.map,characters:resolved.application.characters,characterIdByCombatantId:attack.characterIdByCombatantId},attack.targetToken.id,attack.actorToken.id,shieldTargetCharacter) : undefined
        returnAccepted = returnAccepted && returnTarget != null
        const returnTargetId = returnTarget?.id ?? attack.actorToken.id
